'use client';
import {useCallback,useEffect,useMemo,useRef,useState, type FormEvent, type ReactNode} from 'react';
import {ArrowUpRight,ArrowRight,ArrowDown,Plus,RotateCcw,Check,X,Clock3,CalendarDays,SlidersHorizontal,Link2,Focus,LayoutDashboard,ChevronLeft,ChevronRight,Bell,Download,Upload,Play,Pause,Sparkles,CheckCheck,ExternalLink,Trash2,Pencil,ShieldCheck,Menu,Volume2,MoveUpRight,Orbit as OrbitIcon,BookOpen,AlertTriangle,Copy,Lock,Search,Command,ClipboardCheck,FileCheck2} from 'lucide-react';
import Orbit from '@/components/orbit';
import Experience from '@/components/experience';
import BrandMark from '@/components/brand-mark';
import {dueReminders} from '@/lib/reminders';
